#!/usr/bin/env python3
"""
Neutron Cross-Section Data Processor
Processes neutron cross-section data files and calculates macroscopic cross-sections and reaction rates.
"""

import os
import json
import re
import math
from functools import cmp_to_key

# Constants
DATA_DIR = "/app/data/cross_sections"
DENSITY_FILE = "/app/data/atomic_densities.txt"
OUTPUT_FILE = "/app/cross_section_report.json"
THERMAL_ENERGY = 0.025  # eV
THERMAL_TOLERANCE = 0.1  # eV
AVOGADRO = 6.02214076e23  # atoms/mol
BARN_TO_CM2 = 1e-24


def get_depth(filepath, base_dir):
    """Calculate depth of file relative to base_dir."""
    rel_path = os.path.relpath(filepath, base_dir)
    parts = rel_path.split(os.sep)
    depth = len(parts) - 1
    return depth


def sort_files_recursive(base_dir):
    """
    Find all .xs files and sort them:
    - Deepest directories first (most nested files first) 
    - Within same depth, reverse alphabetical by full path (Z to A, case-sensitive)
    """
    xs_files = []
    if not os.path.exists(base_dir):
        return xs_files

    for root, dirs, files in os.walk(base_dir):
        for f in files:
            if f.endswith('.xs'):
                xs_files.append(os.path.join(root, f))

    # Sort: depth descending, then path descending (reverse alpha)
    xs_files.sort(key=lambda x: (get_depth(x, base_dir), x), reverse=True)
    return xs_files


def normalize_isotope_name(name):
    """Normalize isotope name for comparison: lowercase, remove spaces and hyphens."""
    return name.lower().replace(' ', '').replace('-', '')


def parse_isotope_name(name):
    """
    Parse isotope name to extract element and mass number.
    Returns (element, mass) or None if parsing fails.
    """
    name_lower = name.lower()
    match = re.match(r'^([a-z]+)(?:-?)(\d*)$', name_lower)
    if match:
        element = match.group(1)
        mass_str = match.group(2)
        if mass_str:
            mass = int(mass_str)
            return (element, mass)
    return None


def load_atomic_densities(filepath):
    """Load atomic densities from file."""
    densities = {}
    try:
        with open(filepath, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                parts = line.split(':')
                if len(parts) >= 3:
                    iso_name = parts[0].strip()
                    try:
                        density = float(parts[1].strip())
                        atomic_mass = float(parts[2].strip())
                        norm_key = normalize_isotope_name(iso_name)
                        densities[norm_key] = (density, atomic_mass)
                    except ValueError:
                        continue
    except Exception:
        pass
    return densities


def find_density_match(isotope_name, density_data):
    """Find matching density data for isotope."""
    if isotope_name in density_data:
        return density_data[isotope_name]
    if isotope_name.lower() in density_data:
        return density_data[isotope_name.lower()]
    norm_name = normalize_isotope_name(isotope_name)
    if norm_name in density_data:
        return density_data[norm_name]
    return None


def parse_xs_file(filepath):
    """Parse a cross-section file. Returns list of tuples."""
    entries = []
    current_isotope = None

    try:
        with open(filepath, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue

                if line.startswith('ISOTOPE:'):
                    current_isotope = line[8:].strip()
                elif line.startswith('ENERGY:'):
                    content = line[7:].strip()
                    parts = content.split()

                    energy = None
                    sigma_t = None
                    sigma_a = None
                    sigma_s = None

                    for part in parts:
                        if part.startswith('SIGMA_T:'):
                            sigma_t = float(part[8:])
                        elif part.startswith('SIGMA_A:'):
                            sigma_a = float(part[8:])
                        elif part.startswith('SIGMA_S:'):
                            sigma_s = float(part[8:])
                        else:
                            try:
                                energy = float(part)
                            except ValueError:
                                pass

                    if energy is not None and current_isotope is not None:
                        entries.append((current_isotope, energy, sigma_t, sigma_a, sigma_s))
    except Exception as e:
        raise Exception(f"Error reading {filepath}: {e}")

    return entries


def validate_entries(entries):
    """Validate parsed entries. Returns (is_valid, sorted_errors)."""
    errors = []

    if not entries:
        return (False, ["invalid_format"])

    energies = [e[1] for e in entries]
    sigmas = [(e[2], e[3], e[4]) for e in entries]

    # First energy > 0
    if energies[0] <= 0:
        errors.append("invalid_energy_ordering")

    # Energies strictly increasing
    for i in range(len(energies) - 1):
        if energies[i+1] <= energies[i]:
            errors.append("invalid_energy_ordering")
            break

    # Non-negative cross-sections
    for st, sa, ss in sigmas:
        if st < 0 or sa < 0 or ss < 0:
            errors.append("negative_cross_section")
            break

    # SIGMA_T = SIGMA_A + SIGMA_S (within 0.001)
    for st, sa, ss in sigmas:
        if abs(st - (sa + ss)) > 0.001:
            errors.append("cross_section_mismatch")
            break

    # NaN or Infinity
    for st, sa, ss in sigmas:
        if math.isnan(st) or math.isinf(st) or math.isnan(sa) or math.isinf(sa) or math.isnan(ss) or math.isinf(ss):
            errors.append("cross_section_mismatch")
            break

    return (len(errors) == 0, sorted(errors))


def find_thermal_xs(entries):
    """Find thermal cross-section at 0.025 eV. Returns (sigma_s, status)."""
    target = THERMAL_ENERGY
    tolerance = THERMAL_TOLERANCE

    candidates = []
    for entry in entries:
        energy = entry[1]
        sigma_s = entry[4]
        if abs(energy - target) <= tolerance:
            candidates.append((energy, sigma_s))

    if not candidates:
        return (None, "insufficient_data")

    # Check for exact match
    for e, s in candidates:
        if abs(e - target) < 1e-10:
            return (s, "valid")

    # Find minimum distance
    min_dist = min(abs(e - target) for e, s in candidates)
    closest = [(e, s) for e, s in candidates if abs(e - target) == min_dist]

    # Tie: pick higher energy
    best = max(closest, key=lambda x: x[0])
    return (best[1], "valid")


def get_atomic_number(element):
    """Get atomic number (Z) from element symbol."""
    z_map = {
        'h': 1, 'he': 2, 'li': 3, 'be': 4, 'b': 5, 'c': 6, 'n': 7, 'o': 8,
        'f': 9, 'ne': 10, 'na': 11, 'mg': 12, 'al': 13, 'si': 14, 'p': 15,
        's': 16, 'cl': 17, 'ar': 18, 'k': 19, 'ca': 20, 'sc': 21, 'ti': 22,
        'v': 23, 'cr': 24, 'mn': 25, 'fe': 26, 'co': 27, 'ni': 28, 'cu': 29,
        'zn': 30, 'ga': 31, 'ge': 32, 'as': 33, 'se': 34, 'br': 35, 'kr': 36,
        'rb': 37, 'sr': 38, 'y': 39, 'zr': 40, 'nb': 41, 'mo': 42, 'tc': 43,
        'ru': 44, 'rh': 45, 'pd': 46, 'ag': 47, 'cd': 48, 'in': 49, 'sn': 50,
        'sb': 51, 'te': 52, 'i': 53, 'xe': 54, 'cs': 55, 'ba': 56, 'la': 57,
        'ce': 58, 'pr': 59, 'nd': 60, 'pm': 61, 'sm': 62, 'eu': 63, 'gd': 64,
        'tb': 65, 'dy': 66, 'ho': 67, 'er': 68, 'tm': 69, 'yb': 70, 'lu': 71,
        'hf': 72, 'ta': 73, 'w': 74, 're': 75, 'os': 76, 'ir': 77, 'pt': 78,
        'au': 79, 'hg': 80, 'tl': 81, 'pb': 82, 'bi': 83, 'po': 84, 'at': 85,
        'rn': 86, 'fr': 87, 'ra': 88, 'ac': 89, 'th': 90, 'pa': 91, 'u': 92
    }
    return z_map.get(element, 0)


def parse_isotope_key(isotope_name):
    """Parse isotope name to (Z, A, name)."""
    parsed = parse_isotope_name(isotope_name)
    if parsed is None:
        return (0, 0, isotope_name)
    element, mass = parsed
    z = get_atomic_number(element)
    return (z, mass, isotope_name)


def iso_compare(r1, r2):
    """Compare two isotope results for sorting."""
    z1, a1, n1 = parse_isotope_key(r1["isotope"])
    z2, a2, n2 = parse_isotope_key(r2["isotope"])

    if z1 != z2:
        return z2 - z1
    if a1 != a2:
        return a2 - a1
    if n1 < n2:
        return 1
    elif n1 > n2:
        return -1
    return 0


def write_json_report_atomic(report):
    """Write report atomically using .tmp file."""
    tmp_file = OUTPUT_FILE + ".tmp"
    with open(tmp_file, 'w') as f:
        json.dump(report, f, indent=2)
    os.rename(tmp_file, OUTPUT_FILE)


def round6(x):
    """Round to 6 decimal places using Python's round (banker's rounding)."""
    if x is None:
        return None
    return round(x, 6)


def main():
    total_files = 0
    valid_files = 0
    invalid_files = 0

    xs_files = []
    if os.path.exists(DATA_DIR):
        xs_files = sort_files_recursive(DATA_DIR)
        total_files = len(xs_files)

    density_data = load_atomic_densities(DENSITY_FILE)
    seen_isotopes = {}  # norm_name -> (original_name, source_file)
    isotope_results = []

    for filepath in xs_files:
        rel_path = os.path.relpath(filepath, DATA_DIR)

        try:
            entries = parse_xs_file(filepath)
        except Exception:
            invalid_files += 1
            continue

        valid_files += 1

        # Group by isotope name
        isotope_map = {}
        for entry in entries:
            iso_name = entry[0]
            if iso_name not in isotope_map:
                isotope_map[iso_name] = []
            isotope_map[iso_name].append(entry)

        for iso_name, iso_entries in isotope_map.items():
            norm_name = normalize_isotope_name(iso_name)

            if norm_name in seen_isotopes:
                # Duplicate isotope
                first_iso_name, _ = seen_isotopes[norm_name]
                result = {
                    "isotope": first_iso_name,
                    "source_file": rel_path,
                    "status": "duplicate_isotope",
                    "atomic_density_atoms_cm3": None,
                    "macroscopic_cross_section_cm_minus1": None,
                    "reaction_rate_reactions_cm3_s": None,
                    "thermal_xs_barns": None,
                    "validation_errors": []
                }
            else:
                seen_isotopes[norm_name] = (iso_name, rel_path)
                is_valid, validation_errors = validate_entries(iso_entries)

                status = "valid"

                # Apply validation errors with priority
                if not is_valid:
                    if "cross_section_mismatch" in validation_errors:
                        status = "cross_section_mismatch"
                    elif "invalid_energy_ordering" in validation_errors:
                        status = "invalid_energy_ordering"
                    elif "negative_cross_section" in validation_errors:
                        status = "negative_cross_section"
                    else:
                        status = "invalid_format"

                # Check thermal data (only if status still valid)
                thermal_xs = None
                thermal_xs_barns = None
                if status == "valid":
                    thermal_xs, thermal_status = find_thermal_xs(iso_entries)
                    if thermal_status == "insufficient_data":
                        status = "insufficient_data"
                    else:
                        thermal_xs_barns = round6(thermal_xs)

                # Check density and calculate values (only if status still valid)
                atomic_density_atoms_cm3 = None
                macroscopic_cross_section_cm_minus1 = None
                reaction_rate_reactions_cm3_s = None
                if status == "valid":
                    density_info = find_density_match(iso_name, density_data)
                    if density_info is None:
                        status = "missing_density_data"
                    else:
                        density, atomic_mass = density_info
                        N_unrounded = (density / atomic_mass) * AVOGADRO
                        N_rounded = round6(N_unrounded)

                        sigma_cm2 = thermal_xs * BARN_TO_CM2
                        macro_xs_unrounded = N_unrounded * sigma_cm2
                        macro_xs_rounded = round6(macro_xs_unrounded)

                        reaction_rate = 1e14 * macro_xs_rounded
                        reaction_rate_rounded = round6(reaction_rate)

                        atomic_density_atoms_cm3 = N_rounded
                        macroscopic_cross_section_cm_minus1 = macro_xs_rounded
                        reaction_rate_reactions_cm3_s = reaction_rate_rounded

                # Check isotope name validity
                if status == "valid":
                    parsed = parse_isotope_name(iso_name)
                    if parsed is None:
                        status = "invalid_isotope_name"

                result = {
                    "isotope": iso_name,
                    "source_file": rel_path,
                    "status": status,
                    "atomic_density_atoms_cm3": atomic_density_atoms_cm3,
                    "macroscopic_cross_section_cm_minus1": macroscopic_cross_section_cm_minus1,
                    "reaction_rate_reactions_cm3_s": reaction_rate_reactions_cm3_s,
                    "thermal_xs_barns": thermal_xs_barns,
                    "validation_errors": validation_errors
                }

            isotope_results.append(result)

    # Sort isotopes
    isotope_results.sort(key=cmp_to_key(iso_compare))

    total_isotopes = len(isotope_results)
    valid_isotopes = sum(1 for r in isotope_results if r["status"] == "valid")
    invalid_isotopes = total_isotopes - valid_isotopes

    report = {
        "total_files": total_files,
        "valid_files": valid_files,
        "invalid_files": invalid_files,
        "total_isotopes": total_isotopes,
        "valid_isotopes": valid_isotopes,
        "invalid_isotopes": invalid_isotopes,
        "isotopes": isotope_results
    }

    write_json_report_atomic(report)


if __name__ == "__main__":
    main()
